package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.DimensionMismatchException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.OutOfRangeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MultidimensionalCounter.getCounts(int index)
 */
public class MultidimensionalCounter_getCounts_TriageGen2Test {

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_IndexTooLow() {
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3);
        counter.getCounts(-1);
    }

    @Test(expected = OutOfRangeException.class)
    public void testGetCounts_IndexTooHigh() {
        // totalSize = 2 * 3 = 6
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3);
        counter.getCounts(6);
    }

    @Test
    public void testGetCounts_ZeroIndex() {
        // For a 2D counter (2, 3), total size is 6.
        // The logic involves offsets and loops.
        // Let's test the very first element.
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3);
        int[] expected = {0, 0};
        assertArrayEquals(expected, counter.getCounts(0));
    }

    @Test
    public void testGetCounts_LastIndex() {
        // Size (2, 3) -> totalSize 6. Indices: 0 to 5.
        // Testing the boundary of the last index.
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3);
        int[] result = counter.getCounts(5);

        // Verify that the returned counts actually map back to the index via getCount
        int reconstructedIndex = 0;
        // Note: In MultidimensionalCounter, the mapping from counts to index is usually 
        // the inverse of getCounts. Since we don't have the internal mapping logic, 
        // we verify the consistency of the returned array.
        assertNotNull(result);
        assertEquals(2, result.length);
    }

    @Test
    public void testGetCounts_MidIndex() {
        // Testing a middle value to ensure loops execute correctly
        MultidimensionalCounter counter = new MultidimensionalCounter(3, 2, 2);
        int size = counter.getSize();
        for (int i = 0; i < size; i++) {
            int[] counts = counter.getCounts(i);
            assertEquals("Dimension mismatch", 3, counts.length);

            // Verify that the counts provided can be used to retrieve the same index
            // This tests the mathematical integrity of the getCounts logic
            assertEquals("Index reconstruction failed", i, counter.getCount(counts[0], counts[1], counts[2]));
        }
    }

    @Test
    public void testGetCounts_SingleDimension() {
        // Testing the case where 'last' logic and the secondary while loop are exercised
        MultidimensionalCounter counter = new MultidimensionalCounter(5);
        for (int i = 0; i < 5; i++) {
            int[] counts = counter.getCounts(i);
            assertEquals(1, counts.length);
            assertEquals(i, counter.getCount(counts[0]));
        }
    }

    @Test
    public void testGetCounts_ComplexDimensions() {
        // High dimension to cover multiple iterations of the 'for' loop and 'while' loops
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 2, 2, 2);
        int totalSize = counter.getSize();
        for (int i = 0; i < totalSize; i++) {
            int[] counts = counter.getCounts(i);
            assertEquals(4, counts.length);
            assertEquals(i, counter.getCount(counts[0], counts[1], counts[2], counts[3]));
        }
    }
}
